return {["scripts/quests/abyssea/Uleguerand_Dominion_Op_09.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_09.lua",["SHA256"]="5c18ded587f73f6508111ed4997c805c525341d364ba64f25a85ff9c1e8e0226",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #09\n-----------------------------------\n-- !addquest 8 109\n-- Dominion Sergeant (Romaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_09_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Ectozoon'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 582)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_10.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_10.lua",["SHA256"]="95575827cd58c78b90ff0a8b8244e9e61a3ca4b294a0d557d5caa2f3de15a5a1",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #10\n-----------------------------------\n-- !addquest 8 110\n-- Dominion Sergeant (Romaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_10_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Hoarmite'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 583)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_11.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_11.lua",["SHA256"]="0489c53b032949e2a89873c60f62dd0b41b115a08b454efcfa30ab0a3e5f4cff",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #11\n-----------------------------------\n-- !addquest 8 111\n-- Dominion Sergeant (Zazarg's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_11_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Ermit_Imp'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 584)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_12.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_12.lua",["SHA256"]="ebc16c44071578d175b4461786482a44967e023d11a8a7207d3f50f37f95c694",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #12\n-----------------------------------\n-- !addquest 8 112\n-- Dominion Sergeant (Zazarg's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_12_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Benumbed_Vodoriga'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 585)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_13.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_13.lua",["SHA256"]="8d914b649fcad9556b5cb04ba2268d6cce0e5e4cb6209c1e05a3fce39e2e0fa3",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #13\n-----------------------------------\n-- !addquest 8 113\n-- Dominion Sergeant (Romaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_13_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Bluffalo'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 586)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_14.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_14.lua",["SHA256"]="05a5bb23be2aee4c068f05e7c393f0dd45859b590cec3b1d41cc53f900944540",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #14\n-----------------------------------\n-- !addquest 8 114\n-- Dominion Sergeant (Romaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_14_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Sierra_Tiger'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 587)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/A_Certain_Substitute_Patrolman.lua"]={["Path"]="scripts/quests/adoulin/A_Certain_Substitute_Patrolman.lua",["SHA256"]="44f01e35a793154b61a53449cea8861e4307ef13e2e33925ac652775af17c96c",["Text"]="-----------------------------------\n-- A Certain Substitute Patrolman\n-----------------------------------\n-- !addquest 9 76\n-- Rising Solstice : !pos -154 4 -29 256\n-- Zaoso           : !pos -94 3 -11 256\n-- Clemmar         : !pos -12 0 12 256\n-- Kongramm        : !pos 61 32 138 256\n-- Virsaint        : !pos 32 0 -5 256\n-- Shipilolo       : !pos 84 0 -60 256\n-- Dangueubert     : !pos 5 0 -136 256\n-- Nylene          : !pos 12 0 -82 256\n-----------------------------------\nlocal westernAdoulinID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_CERTAIN_SUBSTITUTE_PATROLMAN)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n    exp       = 1000,\n}\n\nlocal patrolData =\n{\n    ['Zaoso']       = 0,\n    ['Clemmar']     = 1,\n    ['Kongramm']    = 2,\n    ['Virsaint']    = 3,\n    ['Shipilolo']   = 4,\n    ['Dangueubert'] = 5,\n    ['Nylene']      = 6,\n}\n\nlocal patrolOnTrigger = function(player, npc)\n    local npcOffset = patrolData[npc:getName()]\n\n    if quest:getVar(player, 'Prog') == npcOffset then\n        return quest:progressEvent(2553 + npcOffset)\n    end\nend\n\nlocal patrolOnEventFinish = function(player, csid, option, npc)\n    local npcOffset = patrolData[npc:getName()]\n\n    if quest:getVar(player, 'Prog') == npcOffset then\n        quest:incrementVar(player, 'Prog', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.SOA) >= xi.mission.id.soa.LIFE_ON_THE_FRONTIER\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Rising_Solstice'] = quest:progressEvent(2550),\n\n            onEventFinish =\n            {\n                [2550] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WESTERN_ADOULIN_PATROL_ROUTE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Rising_Solstice'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        return quest:progressEvent(2552)\n                    else\n                        return quest:event(2551)\n                    end\n                end,\n            },\n\n            ['Zaoso'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Clemmar'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Kongramm'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Virsaint'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Shipilolo'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Dangueubert'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Nylene'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            onEventFinish =\n            {\n                [2552] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.WESTERN_ADOULIN_PATROL_ROUTE)\n                        player:messageSpecial(westernAdoulinID.text.KEYITEM_LOST, xi.keyItem.WESTERN_ADOULIN_PATROL_ROUTE)\n                    end\n                end,\n\n                [2553] = patrolOnEventFinish,\n                [2554] = patrolOnEventFinish,\n                [2555] = patrolOnEventFinish,\n                [2556] = patrolOnEventFinish,\n                [2557] = patrolOnEventFinish,\n                [2558] = patrolOnEventFinish,\n                [2559] = patrolOnEventFinish,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/A_Good_Pair_of_Crocs.lua"]={["Path"]="scripts/quests/adoulin/A_Good_Pair_of_Crocs.lua",["SHA256"]="3c80b7323f290a36c7c19742e0e23dd8982d736799aecad691ab8156ebfc0136",["Text"]="-----------------------------------\n-- A Good Pair of Crocs (A_Good_Pair_of_Crocs)\n-- Adoulin Fame Quest Cycle 2/3\n-- https://ffxiclopedia.fandom.com/wiki/A_Good_Pair_of_Crocs\n-- https://www.bg-wiki.com/ffxi/A_Good_Pair_of_Crocs\n-----------------------------------\n-- VELKK_NECKLACE : !additem 3928\n-- VELKK_MASK     : !additem 3929\n-- Felmsy         : !pos -53.111 -0.150 88.456 257\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_GOOD_PAIR_OF_CROCS)\n\n-- NOTE:\n-- It is reported that to reach max fame (~610) you must complete this cycle of quests\n-- around 30 times, for a total of ~100 quests.\n-- 610 / 100 = ~6 fame each\nquest.reward =\n{\n    fame     = 6,\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 200,\n    exp      = 500,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest (First time)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Felmsy'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(3001)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3001] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Begin quest (Repeated)\n    {\n        check = function(player, status, vars)\n            return player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.IT_SETS_MY_HEART_AFLUTTER) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_GOOD_PAIR_OF_CROCS) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_SHOT_IN_THE_DARK) and\n                player:getCharVar('ADOULIN_FAME_QUEST_TRACKER') == 1\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Felmsy'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(3003)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3003] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_GOOD_PAIR_OF_CROCS)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Felmsy'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(3004)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.VELKK_NECKLACE) or\n                        npcUtil.tradeHasExactly(trade, xi.item.VELKK_MASK)\n                    then\n                        return quest:progressEvent(3002)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3002] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setCharVar('ADOULIN_FAME_QUEST_TRACKER', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Completed quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Felmsy'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(3000)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/A_Shot_in_the_Dark.lua"]={["Path"]="scripts/quests/adoulin/A_Shot_in_the_Dark.lua",["SHA256"]="ca6c43438ec26f1b01cc8bf90fd1be847f5f155f9d83b218303d7b90ed1b69fd",["Text"]="-----------------------------------\n-- A Shot in the Dark (A_Shot_in_the_Dark)\n-- Adoulin Fame Quest Cycle 3/3\n-- https://ffxiclopedia.fandom.com/wiki/A_Shot_in_the_Dark\n-- https://www.bg-wiki.com/ffxi/A_Shot_in_the_Dark\n-----------------------------------\n-- UMBRIL_OOZE : !additem 3935\n-- Pudith      : !pos -109.533 -0.150 56.939 257\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_SHOT_IN_THE_DARK)\n\n-- NOTE:\n-- It is reported that to reach max fame (~610) you must complete this cycle of quests\n-- around 30 times, for a total of ~100 quests.\n-- 610 / 100 = ~6 fame each\nquest.reward =\n{\n    fame     = 6,\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 200,\n    exp      = 500,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest (First time)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Pudith'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(3011)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3011] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Begin quest (Repeated)\n    {\n        check = function(player, status, vars)\n            return player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.IT_SETS_MY_HEART_AFLUTTER) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_GOOD_PAIR_OF_CROCS) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_SHOT_IN_THE_DARK) and\n                player:getCharVar('ADOULIN_FAME_QUEST_TRACKER') == 2\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Pudith'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(3013)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3013] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_SHOT_IN_THE_DARK)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Pudith'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(3014)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.UMBRIL_OOZE) then\n                        return quest:progressEvent(3012)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3012] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setCharVar('ADOULIN_FAME_QUEST_TRACKER', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Completed quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Pudith'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(3010)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/A_Stones_Throw_Away.lua"]={["Path"]="scripts/quests/adoulin/A_Stones_Throw_Away.lua",["SHA256"]="a127dcc41d1671795b05b6a528e016b460cf78f39623c1057d82cc7fe6a2c785",["Text"]="-----------------------------------\n-- A Stone's Throw Away\n-----------------------------------\n-- !addquest 9 56\n-- Apolliane : !pos 447.088 -15.846 -320 265\n-----------------------------------\nlocal morimarID = zones[xi.zone.MORIMAR_BASALT_FIELDS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_STONES_THROW_AWAY)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MORIMAR_BASALT_FIELDS] =\n        {\n            ['Apolliane'] = quest:progressEvent(2571),\n\n            onEventFinish =\n            {\n                [2571] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MORIMAR_BASALT_FIELDS] =\n        {\n            ['Apolliane'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- TODO: Morimar Basalt Fields HELM is not implemented at this time.  When it is,\n                    -- on mining a Marble Nugget, set the Prog quest variable to 1, as this quest requires\n                    -- the player to mine this object.\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.MARBLE_NUGGET) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(2573)\n                    end\n                end,\n\n                onTrigger = quest:event(2572),\n            },\n\n            onEventFinish =\n            {\n                [2573] = function(player, csid, option, npc)\n                    player:messageSpecial(morimarID.text.YOU_HAVE_LEARNED, xi.keyItem.DEMOLISHING)\n\n                    if quest:complete(player) then\n                        player:addKeyItem(xi.keyItem.DEMOLISHING)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Breaking_the_Ice.lua"]={["Path"]="scripts/quests/adoulin/Breaking_the_Ice.lua",["SHA256"]="42e4c129142c475053675fa55c628cad265ecaa6f6148c435d5ad02ac7cd94bf",["Text"]="-----------------------------------\n-- Breaking the Ice\n-----------------------------------\n-- !addquest 9 54\n-- Traiffeaux : !pos 437.451 63 -290.512 267\n-----------------------------------\nlocal kamihrID = zones[xi.zone.KAMIHR_DRIFTS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.BREAKING_THE_ICE)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n}\n\nlocal requiredTradeItems =\n{\n    { xi.item.RABBIT_HIDE, 3 },\n    { xi.item.RAAZ_TUSK,   1 },\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.KAMIHR_DRIFTS] =\n        {\n            ['Traiffeaux'] = quest:progressEvent(24),\n\n            onEventFinish =\n            {\n                [24] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KAMIHR_DRIFTS] =\n        {\n            ['Traiffeaux'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, requiredTradeItems) then\n                        -- NOTE: This event may cause Windower to hang part-way through.\n\n                        return quest:progressEvent(26)\n                    end\n                end,\n\n                onTrigger = quest:event(25),\n            },\n\n            onEventFinish =\n            {\n                [26] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.PAIR_OF_FUZZY_EARMUFFS)\n                    player:messageSpecial(kamihrID.text.YOU_HAVE_LEARNED, xi.keyItem.FRAGMENTING)\n\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addKeyItem(xi.keyItem.FRAGMENTING)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Dances_with_Luopans.lua"]={["Path"]="scripts/quests/adoulin/Dances_with_Luopans.lua",["SHA256"]="56ecb93ca846d67f050b93f05244dda1b91a9823e2e27f186d7e360960623c7c",["Text"]="-----------------------------------\n-- Dances with Luopans\n-- Geomancer unlock quest\n-----------------------------------\n-- !addquest 9 118\n-- Sylvie : !pos 78.094 32.000 135.725 256\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.DANCES_WITH_LUOPANS)\n\nxi.dancesWithLuopans = {}\n\nxi.dancesWithLuopans.onHealing = function(player)\n    if\n        quest:getLocalVar(player, 'LocusArea') == 1 and\n        quest:getVar(player, 'Prog') == 0\n    then\n        local ID                = zones[player:getZoneID()]\n        local maxRestSeconds    = 8 * 60\n        local secondsPerTick    = xi.settings.map.HEALING_TICK_DELAY\n        local minWaitTime       = math.min(3 * secondsPerTick, maxRestSeconds)\n        local waitTimeInSeconds = math.randomInt(minWaitTime, maxRestSeconds)\n\n        player:messageSpecial(ID.text.ENERGIES_COURSE)\n        quest:setLocalVar(player, 'RestUntil', GetSystemTime() + waitTimeInSeconds)\n\n        player:timer(waitTimeInSeconds * 1000, function(playerArg)\n            local restUntil = quest:getLocalVar(playerArg, 'RestUntil')\n\n            if\n                restUntil > 0 and\n                GetSystemTime() >= restUntil\n            then\n                playerArg:messageSpecial(ID.text.MYSTICAL_WARMTH)\n                quest:setLocalVar(playerArg, 'RestUntil', 0)\n                quest:setVar(playerArg, 'Prog', 1)\n            end\n        end)\n    end\nend\n\nxi.dancesWithLuopans.onEffectLose = function(player)\n    quest:setLocalVar(player, 'RestUntil', 0)\nend\n\nlocal function onLocusAreaEnter(player, triggerArea)\n    if\n        player:hasKeyItem(xi.keyItem.LUOPAN) and\n        quest:getVar(player, 'Prog') == 0\n    then\n        local ID = zones[player:getZoneID()]\n        player:messageSpecial(ID.text.UNCANNY_SENSATION)\n        quest:setLocalVar(player, 'LocusArea', 1)\n    end\nend\n\nlocal function onLocusAreaLeave(player, triggerArea)\n    quest:setLocalVar(player, 'LocusArea', 0)\n    quest:setLocalVar(player, 'RestUntil', 0)\nend\n\nlocal homelandSoilNation =\n{\n    [xi.zone.LA_THEINE_PLATEAU]    = xi.nation.SANDORIA,\n    [xi.zone.KONSCHTAT_HIGHLANDS]  = xi.nation.BASTOK,\n    [xi.zone.TAHRONGI_CANYON]      = xi.nation.WINDURST,\n}\n\nlocal function onHomelandSoilTrigger(player, npc)\n    if\n        player:getNation() == homelandSoilNation[player:getZoneID()] and\n        not player:hasKeyItem(xi.keyItem.FISTFUL_OF_HOMELAND_SOIL) and\n        not player:hasKeyItem(xi.keyItem.LUOPAN)\n    then\n        npcUtil.giveKeyItem(player, xi.keyItem.FISTFUL_OF_HOMELAND_SOIL)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Sylvie'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Declined') == 1 then\n                        return quest:progressEvent(32)\n                    end\n\n                    return quest:progressEvent(31)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [31] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Declined', 1)\n                    end\n                end,\n\n                [32] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Declined', 0)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CEIZAK_BATTLEGROUNDS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = onLocusAreaEnter,\n                [2] = onLocusAreaEnter,\n            },\n\n            onTriggerAreaLeave =\n            {\n                [1] = onLocusAreaLeave,\n                [2] = onLocusAreaLeave,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['Ergon_Locus'] =\n            {\n                onTrigger = onHomelandSoilTrigger,\n            },\n        },\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            ['Ergon_Locus'] =\n            {\n                onTrigger = onHomelandSoilTrigger,\n            },\n        },\n\n        [xi.zone.TAHRONGI_CANYON] =\n        {\n            ['Ergon_Locus'] =\n            {\n                onTrigger = onHomelandSoilTrigger,\n            },\n        },\n\n        [xi.zone.YAHSE_HUNTING_GROUNDS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = onLocusAreaEnter,\n            },\n\n            onTriggerAreaLeave =\n            {\n                [1] = onLocusAreaLeave,\n            },\n        },\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Sylvie'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(36)\n                    elseif player:hasKeyItem(xi.keyItem.LUOPAN) then\n                        return quest:progressEvent(35)\n                    end\n\n                    return quest:progressEvent(33)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasKeyItem(xi.keyItem.FISTFUL_OF_HOMELAND_SOIL) and\n                        npcUtil.tradeHas(trade, xi.item.PETRIFIED_LOG)\n                    then\n                        return quest:progressEvent(34)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [34] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.FISTFUL_OF_HOMELAND_SOIL)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LUOPAN)\n                end,\n\n                [36] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { xi.item.PLATE_OF_INDI_POISON, xi.item.MATRE_BELL }) then\n                        player:unlockJob(xi.job.GEO)\n                        player:messageSpecial(zones[xi.zone.WESTERN_ADOULIN].text.YOU_CAN_NOW_BECOME, 0)\n                        npcUtil.giveKeyItem(player, xi.keyItem.JOB_GESTURE_GEOMANCER)\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Sylvie'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() == xi.job.GEO and\n                        not player:hasItem(xi.item.MATRE_BELL)\n                    then\n                        quest:setLocalVar(player, 'MatreBellPayment', 0)\n                        return quest:event(37):replaceDefault()\n                    end\n\n                    return quest:event(39):replaceDefault()\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [37] = function(player, csid, option, npc)\n                    if option ~= 1 and option ~= 2 then\n                        return\n                    end\n\n                    quest:setLocalVar(player, 'MatreBellPayment', 0)\n\n                    local eventUpdateParam = 0\n                    if player:getFreeSlotsCount() < 1 then\n                        eventUpdateParam = 2\n                    elseif\n                        (option == 1 and player:getGil() >= 300000) or\n                        (option == 2 and player:getCurrency('bayld') >= 150000)\n                    then\n                        quest:setLocalVar(player, 'MatreBellPayment', option)\n                        eventUpdateParam = 1\n                    end\n\n                    player:updateEvent(0, 0, 0, 0, 0, 0, 0, eventUpdateParam)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    local paymentOption = quest:getLocalVar(player, 'MatreBellPayment')\n                    if paymentOption == 0 then\n                        return\n                    end\n\n                    quest:setLocalVar(player, 'MatreBellPayment', 0)\n\n                    if option ~= 1 then\n                        return\n                    end\n\n                    if npcUtil.giveItem(player, { xi.item.MATRE_BELL }) then\n                        if paymentOption == 1 then\n                            player:delGil(300000)\n                        elseif paymentOption == 2 then\n                            player:delCurrency('bayld', 150000)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Flavors_of_Our_Lives.lua"]={["Path"]="scripts/quests/adoulin/Flavors_of_Our_Lives.lua",["SHA256"]="ff833bd086d6de57ec380e2a1a3360d170bf8814e024a931aa5d119db1a35c2f",["Text"]="-----------------------------------\n-- Flavors of Our Lives (Flavors_of_Our_Lives)\n-- https://www.bg-wiki.com/ffxi/Flavors_of_Our_Lives\n-----------------------------------\n-- Berghent         : !pos 95.721 -0.148 -28.680 256\n-- Masad            : !pos -28.182 -0.650 -91.991 256\n-- Dewalt           : !pos -23.099 -0.648 28.208 256\n-- Chalvava         : !pos -318.000 -1.000 -318.000 258\n-- Harvesting Point : !pos 196.000 0.001 289.500 260\n-- Sickle           : !additem 1020\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.FLAVORS_OF_OUR_LIVES)\n\nquest.reward =\n{\n    bayld = 300,\n    exp   = 500,\n    title = xi.title.POTATION_PATHFINDER,\n}\n\nquest.sections =\n{\n    -- Section: Talk to Berghent near the Big Bridge in Western Adoulin (J-9) to start the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('Flavors_of_Our_Lives_Refused') == 1 then\n                        return quest:progressEvent(81)\n                    else\n                        return quest:progressEvent(80)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [80] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else -- Refused\n                        player:setLocalVar('Flavors_of_Our_Lives_Refused', 1)\n                    end\n                end,\n\n                [81] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Talk to Masad inside the Mummers' Coalition.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:event(82), -- Reminder\n\n            ['Masad'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCurrentMission(xi.mission.log_id.SOA) <= xi.mission.id.soa.BUDDING_PROSPECTS then\n                        xi.mission.setVar(player, xi.mission.log_id.SOA, xi.mission.id.soa.BUDDING_PROSPECTS, 'Timer', VanadielUniqueDay() + 1)\n                        xi.mission.setMustZone(player, xi.mission.log_id.SOA, xi.mission.id.soa.BUDDING_PROSPECTS)\n                    end\n\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n\n                    return quest:progressEvent(83)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [83] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Talk to Dewalt inside the Couriers' Coalition.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:event(82),  -- Reminder\n            ['Dewalt']   = quest:progressEvent(85),\n\n            ['Masad'] =\n            {\n                onTrigger = function(player, npc)\n                    local waitTimer = quest:getVar(player, 'Timer')\n\n                    -- Priority changes from blocking to non-blocking after the timer has expired\n                    if waitTimer > VanadielUniqueDay() then\n                        return quest:progressEvent(104)\n                    else\n                        return quest:event(104):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [85] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section: Head to Rala Waterways and talk to Chalvava at (F-11).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:event(82),  -- Reminder\n            ['Dewalt']   = quest:event(105), -- Reminder\n        },\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Chalvava'] = quest:progressEvent(8),\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    -- Section: Go to Yahse Hunting Grounds and harvest a Key Item Blightberry using a Sickle\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3 and not player:hasKeyItem(xi.keyItem.BLIGHTBERRY)\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:event(82),  -- Reminder\n            ['Dewalt']   = quest:event(105), -- Reminder\n        },\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Chalvava'] = quest:event(9) -- Reminder\n        },\n\n        [xi.zone.YAHSE_HUNTING_GROUNDS] =\n        {\n            ['Harvesting_Point'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- No CS for HELM in Adoulin\n                    xi.helm.onTrade(player, npc, trade, xi.helmType.HARVESTING, nil)\n                    return quest:keyItem(xi.keyItem.BLIGHTBERRY)\n                end,\n            },\n        },\n    },\n\n    -- Section: Return to Berghent for your reward\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3 and player:hasKeyItem(xi.keyItem.BLIGHTBERRY)\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:progressEvent(87),\n\n            onEventFinish =\n            {\n                [87] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    -- TODO: remove blightberry\n                end,\n            },\n        },\n    },\n\n    -- New default text\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Berghent'] = quest:event(88),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Hide_and_Go_Peak.lua"]={["Path"]="scripts/quests/adoulin/Hide_and_Go_Peak.lua",["SHA256"]="d07cd51754ae7f80cf405d46e4f6b18b61543bf1621bf28d5cb72db86000eeb0",["Text"]="-----------------------------------\n-- Hide and Go Peak\n-----------------------------------\n-- !addquest 9 57\n-- Toppled Tree    : !pos 356.272 -59.701 149.99 266\n-- Velkk Cache     : !pos 278.126 -0.378 -80.672 266\n-- Scalable Area 2 : !pos 271.483 -59.917 92.095 266\n-----------------------------------\nlocal marjamiID = zones[xi.zone.MARJAMI_RAVINE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.HIDE_AND_GO_PEAK)\n\n-- Note: There are multiple KI rewards here, and A Pair of Velkk Gloves is added prior\n-- to the quest complete to cover this.\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n}\n\n-- Scalable Area climbs, available once the player has earned Climbing + the Pair of Velkk Gloves and completed the quest.\nlocal scalableData =\n{\n    [xi.zone.CIRDAS_CAVERNS]        = { eventBase = 17 },\n    [xi.zone.DHO_GATES]             = { eventBase = 10 },\n    [xi.zone.MARJAMI_RAVINE]        = { eventBase = 14 },\n    [xi.zone.MOH_GATES]             = { eventBase = 12 },\n    [xi.zone.MORIMAR_BASALT_FIELDS] = { eventBase = 40 },\n    [xi.zone.SIH_GATES]             = { eventBase = 17 },\n    [xi.zone.WOH_GATES]             = { eventBase = 200 },\n}\n\nlocal function scalableAreaWarp(player, npc)\n    local zoneId   = player:getZoneID()\n    local data     = scalableData[zoneId]\n    local padIndex = npc:getID() - zones[zoneId].npc.SCALABLE_AREA_OFFSET\n\n    return quest:event(data.eventBase + padIndex, { [5] = padIndex + 1 })\nend\n\nlocal marjamiScalablePads = {}\nfor i = 0, 23 do\n    marjamiScalablePads['Scalable_Area_' .. i] = { onTrigger = scalableAreaWarp }\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MARJAMI_RAVINE] =\n        {\n            ['Toppled_Tree'] = quest:progressEvent(3),\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MARJAMI_RAVINE] =\n        {\n            ['Toppled_Tree'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(4)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(5)\n                    elseif questProgress == 2 then\n                        return quest:event(6)\n                    end\n                end,\n            },\n\n            ['Scalable_Area_2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(7)\n                    end\n                end,\n            },\n\n            ['Velkk_Cache'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.LARGE_STRIP_OF_VELKK_HIDE) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        player:messageSpecial(marjamiID.text.LEATHER_SCRAPS_STREWN)\n                        quest:setVar(player, 'Prog', 1)\n\n                        return quest:keyItem(xi.keyItem.LARGE_STRIP_OF_VELKK_HIDE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.LARGE_STRIP_OF_VELKK_HIDE)\n                    quest:setVar(player, 'Prog', 2)\n\n                    player:messageSpecial(marjamiID.text.KEYITEM_LOST, xi.keyItem.LARGE_STRIP_OF_VELKK_HIDE)\n                end,\n\n                [7] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.PAIR_OF_VELKK_GLOVES)\n                    player:addKeyItem(xi.keyItem.CLIMBING)\n                    player:messageSpecial(marjamiID.text.YOU_HAVE_LEARNED, xi.keyItem.CLIMBING)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.CIRDAS_CAVERNS]        = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n        [xi.zone.DHO_GATES]             = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n        [xi.zone.MARJAMI_RAVINE]        = marjamiScalablePads,\n        [xi.zone.MOH_GATES]             = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n        [xi.zone.MORIMAR_BASALT_FIELDS] = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n        [xi.zone.SIH_GATES]             = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n        [xi.zone.WOH_GATES]             = { ['Scalable_Area'] = { onTrigger = scalableAreaWarp } },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Hunger_Strikes.lua"]={["Path"]="scripts/quests/adoulin/Hunger_Strikes.lua",["SHA256"]="0e7834974bb718e16d986dab2a11a2042c9f6770d1fcccb05ea51745d3aaaaf2",["Text"]="-----------------------------------\n-- Hunger Strikes\n-----------------------------------\n-- !addquest 9 76\n-- Westerly Breeze : !pos 62 32 123 256\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.HUNGER_STRIKES)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n    exp      = 1000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Westerly_Breeze'] = quest:progressEvent(2530),\n\n            onEventFinish =\n            {\n                [2530] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        ['Westerly_Breeze'] =\n        {\n            onTrade = function(player, npc, trade)\n                if npcUtil.tradeHasExactly(trade, xi.item.BOWL_OF_WISDOM_SOUP) then\n                    return quest:progressEvent(2532)\n                elseif\n                    trade:getItemCount() == 1 and\n                    trade:getGil() == 0\n                then\n                    local itemObj = trade:getItem(0)\n                    local auctionCategory = itemObj:getAHCat()\n\n                    if\n                        auctionCategory >= xi.itemAHCategory.MEAT_EGGS and\n                        auctionCategory <= xi.itemAHCategory.SWEETS\n                    then\n                        return quest:event(2533)\n                    end\n                end\n            end,\n\n            onTrigger = quest:event(2531),\n        },\n\n        onEventFinish =\n        {\n            [2532] = function(player, csid, option, npc)\n                if quest:complete(player) then\n                    player:confirmTrade()\n\n                    xi.quest.setVar(player, xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_STARVING, 'Timer', VanadielUniqueDay() + 1)\n                end\n            end,\n\n            [2533] = function(player, csid, option, npc)\n                player:confirmTrade()\n            end,\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Im_on_a_Boat.lua"]={["Path"]="scripts/quests/adoulin/Im_on_a_Boat.lua",["SHA256"]="a7d9d1478c0d021b2be927671a4db4376fe0ae2b0755d7fa75699edbb2b793a6",["Text"]="-----------------------------------\n-- I'm on a Boat\n-----------------------------------\n-- !addquest 9 55\n-- Choubollet      : !pos 380.818 -2.094 290.792 262\n-- Castoff_Point_4 : !pos 220 0.800 146 262\n-----------------------------------\nlocal foretID = zones[xi.zone.FORET_DE_HENNETIEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.IM_ON_A_BOAT)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n}\n\nlocal requiredTradeItems =\n{\n    { xi.item.SQUARE_OF_DHALMEL_LEATHER, 3 },\n    { xi.item.UMBRIL_OOZE,               1 },\n    { xi.item.TWITHERYM_SCALE,           1 },\n}\n\n-- Castoff Point navigation, available once the player has earned Watercrafting and completed the quest.\nlocal castoffData =\n{\n    [xi.zone.CIRDAS_CAVERNS]        = { eventId = 11, pad0Bank = 1 },\n    [xi.zone.FORET_DE_HENNETIEL]    = { eventId = 18, isRiverRoute = true },\n    [xi.zone.MORIMAR_BASALT_FIELDS] = { eventId = 18, pad0Bank = 0 },\n    [xi.zone.SIH_GATES]             = { eventId = 12, pad0Bank = 1 },\n    [xi.zone.YAHSE_HUNTING_GROUNDS] = { eventId = 16, pad0Bank = 0 },\n}\n\nlocal function castoffPointWarp(player, npc)\n    local zoneId   = player:getZoneID()\n    local data     = castoffData[zoneId]\n    local padIndex = npc:getID() - zones[zoneId].npc.CASTOFF_POINT_OFFSET\n    if data.isRiverRoute then\n        return quest:event(data.eventId, padIndex)\n    end\n\n    return quest:event(data.eventId, (data.pad0Bank + padIndex) % 2)\nend\n\n-- Foret's six river docks all navigatable post quest.\nlocal foretCastoffPads = {}\nfor i = 0, 5 do\n    foretCastoffPads['Castoff_Point_' .. i] = { onTrigger = castoffPointWarp }\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.FORET_DE_HENNETIEL] =\n        {\n            ['Choubollet'] = quest:progressEvent(2561),\n\n            onEventFinish =\n            {\n                [2561] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.FORET_DE_HENNETIEL] =\n        {\n            ['Choubollet'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, requiredTradeItems)\n                    then\n                        return quest:progressEvent(2576)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.WATERCRAFT) then\n                        return quest:event(2562)\n                    elseif quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(2563)\n                    else\n                        return quest:event(2577)\n                    end\n                end,\n            },\n\n            ['Castoff_Point_4'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.WATERCRAFT) then\n                        local hasTitle = player:hasTitle(xi.title.TOXIN_TUSSLER) and 1 or 0\n\n                        return quest:event(19, 4, hasTitle)\n                    end\n                end,\n            },\n\n            ['Castoff_Point_5'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.WATERCRAFT) then\n                        local hasTitle = player:hasTitle(xi.title.TOXIN_TUSSLER) and 1 or 0\n\n                        return quest:event(19, 5, hasTitle)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    local castoffPointNum = tonumber(string.sub(npc:getName(), -1))\n                    local questProgress   = quest:getVar(player, 'Prog')\n\n                    if option == 1 and questProgress < 2 then\n                        if castoffPointNum == 4 then\n                            quest:setVar(player, 'Prog', 1)\n                            player:messageSpecial(foretID.text.STARTED_TO_LEARN_BOAT)\n                        elseif castoffPointNum == 5 then\n                            quest:setVar(player, 'Prog', 2)\n                            player:messageName(foretID.text.FIGURED_OUT_BOAT, nil)\n                        end\n                    elseif option == 3 then\n                        player:addTitle(xi.title.TOXIN_TUSSLER)\n                    end\n                end,\n\n                [2563] = function(player, csid, option, npc)\n                    player:messageSpecial(foretID.text.YOU_HAVE_LEARNED, xi.keyItem.WATERCRAFTING)\n\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.WATERCRAFT)\n                        player:addKeyItem(xi.keyItem.WATERCRAFTING)\n                    end\n                end,\n\n                [2576] = function(player, csid, option, npc)\n                    player:confirmTrade()\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.WATERCRAFT)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.CIRDAS_CAVERNS]        = { ['Castoff_Point'] = { onTrigger = castoffPointWarp } },\n        [xi.zone.FORET_DE_HENNETIEL]    = foretCastoffPads,\n        [xi.zone.MORIMAR_BASALT_FIELDS] = { ['Castoff_Point'] = { onTrigger = castoffPointWarp } },\n        [xi.zone.SIH_GATES]             = { ['Castoff_Point'] = { onTrigger = castoffPointWarp } },\n        [xi.zone.YAHSE_HUNTING_GROUNDS] = { ['Castoff_Point'] = { onTrigger = castoffPointWarp } },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/It_Sets_My_Heart_Aflutter.lua"]={["Path"]="scripts/quests/adoulin/It_Sets_My_Heart_Aflutter.lua",["SHA256"]="b03efd1c8d8eaf7ea3b80c8782118e369701a72d9af42983be26a2b0fe2cce5d",["Text"]="-----------------------------------\n-- It Sets My Heart Aflutter (It_Sets_My_Heart_Aflutter)\n-- Adoulin Fame Quest Cycle 1/3\n-- https://ffxiclopedia.fandom.com/wiki/It_Sets_My_Heart_Aflutter\n-- https://www.bg-wiki.com/ffxi/It_Sets_My_Heart_Aflutter\n-----------------------------------\n-- PIONEERS_BADGE : !addkeyitem 2157\n-- TWITHERYM_WING : !additem 3930 2\n-- Saldinor       : !pos -338.882 -1.000 -308.252 258\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.IT_SETS_MY_HEART_AFLUTTER)\n\n-- NOTE:\n-- It is reported that to reach max fame (~610) you must complete this cycle of quests\n-- around 30 times, for a total of ~100 quests.\n-- 610 / 100 = ~6 fame each\nquest.reward =\n{\n    fame     = 6,\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 200,\n    exp      = 500,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest (First time)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:hasKeyItem(xi.keyItem.PIONEERS_BADGE)\n        end,\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Saldinor'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(330)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [330] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Begin quest (Repeated)\n    {\n        check = function(player, status, vars)\n            return player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.IT_SETS_MY_HEART_AFLUTTER) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_GOOD_PAIR_OF_CROCS) and\n                player:hasCompletedQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_SHOT_IN_THE_DARK) and\n                player:getCharVar('ADOULIN_FAME_QUEST_TRACKER') == 0\n        end,\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Saldinor'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(332)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [332] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.IT_SETS_MY_HEART_AFLUTTER)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Saldinor'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(333)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.TWITHERYM_WING, 2 } }) then\n                        return quest:progressEvent(331)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [331] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setCharVar('ADOULIN_FAME_QUEST_TRACKER', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Completed quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['Saldinor'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(329)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Lerenes_Lament.lua"]={["Path"]="scripts/quests/adoulin/Lerenes_Lament.lua",["SHA256"]="ebfa86865fc17c49320ee2df3d5bd978755d52cd6d168ba3cc42e663c8c4568f",["Text"]="-----------------------------------\n-- Lerene's Lament\n-----------------------------------\n-- !addquest 9 126\n-- Lerene : !pos -46.876 -179.334 -28.602 274\n-----------------------------------\nlocal outerRaKaznarID = zones[xi.zone.OUTER_RAKAZNAR]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.LERENES_LAMENT)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.OUTER_RAKAZNAR] =\n        {\n            ['Lerene'] = quest:progressEvent(22),\n\n            onEventFinish =\n            {\n                [22] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.OUTER_RAKAZNAR] =\n        {\n            ['Lerene'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.SQUARE_OF_ANCESTRAL_CLOTH, 2 } }) then\n                        return quest:progressEvent(24)\n                    end\n                end,\n\n                onTrigger = quest:event(23),\n            },\n\n            onEventFinish =\n            {\n                [24] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LERENES_PATEN)\n                    player:messageSpecial(outerRaKaznarID.text.YOU_HAVE_LEARNED, xi.keyItem.PULVERIZING)\n\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addKeyItem(xi.keyItem.PULVERIZING)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/The_Longest_Way_Round.lua"]={["Path"]="scripts/quests/adoulin/The_Longest_Way_Round.lua",["SHA256"]="5cd815a720aaccdeab592b826d86a89a63ea52caeed4004c73dac8ce0c47f8c8",["Text"]="-----------------------------------\n-- The Longest Way Round...\n-----------------------------------\n-- !addquest 9 91\n-- Vastran        : !pos -118.93 -0.15 -8.813 257\n-- Fostaig        : !pos -84.806 -0.15 14.079 257\n-- Lamaron        : !pos -52.352 -0.65 96.708 257\n-- Irate Destrier : !pos -72.986 -0.15 -34.96 257\n-- Nhili Uvolep   : !pos 24.06 -22.15 34.488 257\n-- Ploh Trishbahk : !pos 100.58 -40.15 -63.83 257\n-- Cunegonde      : !pos -55.964 -0.15 -129.833 257\n-- Ndah Tolohjin  : !pos -86.808 0.001 -36.867 257\n-----------------------------------\nlocal easternAdoulinID = zones[xi.zone.EASTERN_ADOULIN]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_LONGEST_WAY_ROUND)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 500,\n    exp      = 1000,\n}\n\nlocal patrolData =\n{\n    ['Fostaig']        = 0,\n    ['Lamaron']        = 1,\n    ['Irate_Destrier'] = 2,\n    ['Nhili_Uvolep']   = 3,\n    ['Ploh_Trishbahk'] = 4,\n    ['Cunegonde']      = 5,\n    ['Ndah_Tolohjin']  = 6,\n}\n\nlocal patrolOnTrigger = function(player, npc)\n    local npcOffset = patrolData[npc:getName()]\n\n    if quest:getVar(player, 'Prog') == npcOffset then\n        return quest:progressEvent(2513 + npcOffset)\n    end\nend\n\nlocal patrolOnEventFinish = function(player, csid, option, npc)\n    local npcOffset = patrolData[npc:getName()]\n\n    if quest:getVar(player, 'Prog') == npcOffset then\n        quest:incrementVar(player, 'Prog', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.SOA) >= xi.mission.id.soa.LIFE_ON_THE_FRONTIER\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Vastran'] = quest:progressEvent(2510),\n\n            onEventFinish =\n            {\n                [2510] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.EASTERN_ADOULIN_PATROL_ROUTE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Vastran'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        return quest:progressEvent(2512)\n                    else\n                        return quest:event(2511)\n                    end\n                end,\n            },\n\n            ['Fostaig'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Lamaron'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Irate_Destrier'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Nhili_Uvolep'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Ploh_Trishbahk'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Cunegonde'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            ['Ndah_Tolohjin'] =\n            {\n                onTrigger = patrolOnTrigger,\n            },\n\n            onEventFinish =\n            {\n                [2512] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.EASTERN_ADOULIN_PATROL_ROUTE)\n                        player:messageSpecial(easternAdoulinID.text.LOST_KEYITEM, xi.keyItem.EASTERN_ADOULIN_PATROL_ROUTE)\n                    end\n                end,\n\n                [2513] = patrolOnEventFinish,\n                [2514] = patrolOnEventFinish,\n                [2515] = patrolOnEventFinish,\n                [2516] = patrolOnEventFinish,\n                [2517] = patrolOnEventFinish,\n                [2518] = patrolOnEventFinish,\n                [2519] = patrolOnEventFinish,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/The_Starving.lua"]={["Path"]="scripts/quests/adoulin/The_Starving.lua",["SHA256"]="c970011033df778a2e04e4bfabf5ef24cee2655131695c40671892bb13a5740b",["Text"]="-----------------------------------\n-- The Starving\n-----------------------------------\n-- !addquest 9 84\n-- Westerly Breeze : !pos 62 32 123 256\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_STARVING)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    exp      = 1000,\n    bayld    = 500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Westerly_Breeze'] = quest:progressEvent(3005),\n\n            onEventFinish =\n            {\n                [3005] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        ['Westerly_Breeze'] =\n        {\n            onTrade = function(player, npc, trade)\n                if npcUtil.tradeHasExactly(trade, xi.item.BOTTLE_OF_GOBLIN_DRINK) then\n                    return quest:progressEvent(3007)\n                elseif\n                    trade:getItemCount() == 1 and\n                    trade:getGil() == 0\n                then\n                    local itemObj = trade:getItem(0)\n                    local auctionCategory = itemObj:getAHCat()\n\n                    if auctionCategory == xi.itemAHCategory.DRINKS then\n                        return quest:event(3008)\n                    else\n                        return quest:event(3006)\n                    end\n                else\n                    return quest:event(3006)\n                end\n            end,\n\n            onTrigger = quest:event(3006),\n        },\n\n        onEventFinish =\n        {\n            [3007] = function(player, csid, option, npc)\n                if quest:complete(player) then\n                    xi.quest.setMustZone(player, xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS)\n                    xi.quest.setVar(player, xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS, 'Timer', VanadielUniqueDay() + 1)\n                end\n            end,\n\n            [3008] = function(player, csid, option, npc)\n                player:confirmTrade()\n            end,\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/adoulin/Transporting.lua"]={["Path"]="scripts/quests/adoulin/Transporting.lua",["SHA256"]="f8795b1cb170e8ee65a2ef5573290df10f29887060850738d13d25c2bf7642f5",["Text"]="-----------------------------------\n-- Transporting\n-----------------------------------\n-- !addquest 9 82\n-- Vaulois          : !pos 20 0 85 256\n-- Kongramm         : !pos 61 32 138 256\n-- qm_sluice_gate_6 : !pos -563 -5.768 61.5 258\n-----------------------------------\nlocal ralaID = zones[xi.zone.RALA_WATERWAYS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ADOULIN, xi.quest.id.adoulin.TRANSPORTING)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.ADOULIN,\n    bayld    = 300,\n    exp      = 1000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.ADOULIN) >= 2\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Vaulois'] = quest:progressEvent(2590),\n\n            onEventFinish =\n            {\n                [2590] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MISDELIVERED_PARCEL)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Kongramm'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(2592)\n                    end\n                end,\n            },\n\n            ['Vaulois'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(2591)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2591] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [2592] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.RALA_WATERWAYS] =\n        {\n            ['qm_sluice_gate_6'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(2802)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2802] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.MISDELIVERED_PARCEL)\n                    player:messageSpecial(ralaID.text.KEYITEM_LOST, xi.keyItem.MISDELIVERED_PARCEL)\n\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/A_Taste_of_Honey.lua"]={["Path"]="scripts/quests/ahtUrhgan/A_Taste_of_Honey.lua",["SHA256"]="fe865546deb8befe95f3b85e5c627f0efc969352dd660ab140f040da4ad7405b",["Text"]="-----------------------------------\n-- A Taste of Honey\n-- Fochacha, Whitegate, !pos 3 -1 -10.781 50\n-- Qutiba, Whitegate, !pos 92 -7.5 -130 50\n-- Ulamaal, Whitegate, !pos 93 -7.5 -128 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.A_TASTE_OF_HONEY)\n\nquest.reward =\n{\n    item = xi.item.IRMIK_HELVASI\n}\n\nlocal pephredoOnTrigger = function(player, npc)\n    if\n        quest:getVar(player, npc:getID()) == 0 and\n        npcUtil.giveItem(player, xi.item.POT_OF_WHITE_HONEY)\n    then\n        quest:setVar(player, npc:getID(), 1, NextJstDay())\n        return quest:noAction()\n    end\nend\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.VANISHING_ACT) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Variable set in ToAU quest 'Vanishing Act'.\n                    if player:needToZone() or quest:getVar(player, 'Stage') > GetSystemTime() then\n                        return quest:event(55)\n                    end\n\n                    return quest:progressEvent(579)\n                end,\n            },\n\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(50)\n                end,\n            },\n\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() or quest:getVar(player, 'Stage') > GetSystemTime() then\n                        return quest:event(56)\n                    end\n\n                    return quest:progressEvent(579)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [579] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Stage', 0)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Qutiba'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.POT_OF_WHITE_HONEY, 3 } }) then\n                        return quest:progressEvent(580)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(585)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [580] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Pephredo_Hive'] = pephredoOnTrigger,\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Qutiba'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.POT_OF_WHITE_HONEY, 1 } }) then\n                        return quest:progressEvent(581)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    player:setLocalVar('recipe', 57)\n                    return quest:event(57)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [581] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [57] = function(player, csid, option, npc)\n                    if player:getLocalVar('recipe') == 57 then\n                        player:setLocalVar('recipe', 1)\n                        player:updateEvent(5579, 1, 255, 0, 67108863, 5976652, 4095, 0)\n                    elseif player:getLocalVar('recipe') == 1 then\n                        player:setLocalVar('recipe', 2)\n                        player:updateEvent(4096, 615, 936, 1523, 67108863, 5976652, 4, 0)\n                    elseif player:getLocalVar('recipe') == 2 then\n                        player:setLocalVar('recipe', 3)\n                        player:updateEvent(2214, 2237, 4509, 5568)\n                    elseif player:getLocalVar('recipe') == 3 then\n                        player:setLocalVar('recipe', 0)\n                        player:updateEvent(5575)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Pephredo_Hive'] = pephredoOnTrigger,\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/An_Empty_Vessel.lua"]={["Path"]="scripts/quests/ahtUrhgan/An_Empty_Vessel.lua",["SHA256"]="780bff1add918600a38c76663f0f7d58c2912b084500642dc4ba19c923a2e365",["Text"]="-----------------------------------\n-- An Empty Vessel (BLU Unlock)\n-----------------------------------\n-- Log ID: 6, Quest ID: 5\n-- Waoud : !pos 65 -6 -78 50\n-----------------------------------\n-- Every wait on Waoud needs a Vana'diel day change and a zone, in either order.\n-- Event 69 does not spend the day's divination.\n-- Refusing Yasfel deletes the quest. Accepting and refusing warp the player to different spots.\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AN_EMPTY_VESSEL)\n\nquest.reward =\n{\n    title = xi.title.BEARER_OF_THE_MARK_OF_ZAHAK,\n}\n\nlocal requiredItemList =\n{\n    xi.item.SIRENS_TEAR,\n    xi.item.PINCH_OF_VALKURM_SUNSAND,\n    xi.item.DANGRUF_STONE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(60, player:getGil())\n                    else\n                        return quest:event(63)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [60] = function(player, csid, option, npc)\n                    local numCorrect = quest:getLocalVar(player, 'numCorrect')\n\n                    -- Search Correct Option list for provided option, and update answers.\n                    if option < 40 then\n                        local correctOptions = { 2, 6, 9, 12, 13, 18, 21, 24, 26, 30 }\n\n                        for _, correctOption in ipairs(correctOptions) do\n                            if option == correctOption then\n                                quest:setLocalVar(player, 'numCorrect', numCorrect + 1)\n                                break\n                            end\n                        end\n\n                    -- Display test results.\n                    elseif option == 40 then\n                        local successParams = { 10, 20, 30, 40, 60 } -- Spring, Stone, Gale, Flame, Sky\n\n                        if numCorrect < 10 then\n                            player:updateEvent(player:getGil(), 0, 0, 0, 0, 0, 0, successParams[math.floor(numCorrect / 2) + 1])\n                        else\n                            local requiredItem = math.randomInt(1, 3)\n\n                            quest:setVar(player, 'Option', requiredItem)\n                            player:updateEvent(player:getGil(), 0, 0, 0, 0, 0, requiredItem, 70)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [60] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'numCorrect', 0)\n\n                    if option == 50 then\n                        quest:begin(player)\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n\n                    -- Divination completed without an offer.\n                    elseif\n                        option == 45 and\n                        player:getGil() >= 1000\n                    then\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local requiredItem = quest:getVar(player, 'Option')\n\n                    -- The item is not taken. Yasfel asks for it again in Aydeewa.\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { requiredItemList[requiredItem], 1 } })\n                    then\n                        return quest:progressEvent(67, { [6] = requiredItem })\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        if questProgress == 0 then\n                            return quest:progressEvent(65)\n                        elseif questProgress == 1 then\n                            return quest:event(66, { [6] = quest:getVar(player, 'Option') })\n                        elseif questProgress == 2 then\n                            return quest:event(68)\n                        end\n                    else\n                        return quest:event(64)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                -- Event 65 has no menu. The hint follows on the next conversation.\n                [65] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [67] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    local requiredItemID = requiredItemList[quest:getVar(player, 'Option')]\n\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        player:hasItem(requiredItemID)\n                    then\n                        return quest:progressEvent(3, requiredItemID)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    if option == 13 then\n                        if quest:complete(player) then\n                            -- Note: Messages for receiving the below items are handled by the event.\n                            player:unlockJob(xi.job.BLU)\n                            player:addKeyItem(xi.keyItem.MARK_OF_ZAHAK)\n                            player:addKeyItem(xi.keyItem.JOB_GESTURE_BLUE_MAGE)\n\n                            -- quest:complete() wipes quest vars.\n                            quest:setVar(player, 'completeEvent', 1)\n                        end\n\n                        player:setPos(148, -2, 0, 128, xi.zone.AHT_URHGAN_WHITEGATE)\n\n                    -- Player refused Yasfel.\n                    elseif option == 7 then\n                        quest:setVar(player, 'Prog', 0)\n                        quest:setVar(player, 'Timer', 0)\n                        quest:setVar(player, 'Option', 0)\n\n                        player:delQuest(quest.areaId, quest.questId)\n                        player:setPos(-17.5, -6, 39.6, 171, xi.zone.AHT_URHGAN_WHITEGATE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'completeEvent') == 1 then\n                        return quest:progressEvent(69)\n                    elseif\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:event(78, player:getGil())\n                    else\n                        return quest:event(63)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [78] = function(player, csid, option, npc)\n                    if option == 40 then\n                        player:updateEvent(player:getGil(), 0, 0, 0, 0, 0, 0, math.randomInt(1, 5) * 10)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [69] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'completeEvent', 0)\n                    end\n                end,\n\n                [78] = function(player, csid, option, npc)\n                    if option == 1 and player:getGil() >= 1000 then\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Arts_and_Crafts.lua"]={["Path"]="scripts/quests/ahtUrhgan/Arts_and_Crafts.lua",["SHA256"]="8033319d56c5d54e3eb9a2ec46199bc23bc395d570211476bda3aec59ca234e1",["Text"]="-----------------------------------\n-- Arts and Crafts\n-- Hadahda !pos -112 -7 -66 50\n-- Qutiba !pos 92 -7.5 -130 50\n-- Matifa !pos -10 -1 -9 50\n-- Balakaf !pos 25 -7 126 50\n-- Ekhu Pesshyadha !pos -13 1 103 50\n-- Zabahf !pos -90 -1 10 50\n-- Mathlouq !pos -93 -7 129 50\n-- Mhasbaf !pos 54 -7 11 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ARTS_AND_CRAFTS)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_BRONZE_PIECE,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Hadahda'] = quest:progressEvent(508),\n\n            onEventFinish =\n            {\n                [508] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Hadahda'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:isVarBitsSet(player, 'Prog', 1, 2, 3, 4, 5, 6, 7) then\n                        return quest:progressEvent(517)\n                    else\n                        return quest:event(509)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Stage') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.BOWL_OF_SUTLAC)\n                    then\n                        return quest:progressEvent(573)\n                    end\n                end,\n            },\n\n            ['Mhasbaf'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 1) then\n                        return quest:progressEvent(510)\n                    end\n                end,\n            },\n\n            ['Mathlouq'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 2) then\n                        return quest:progressEvent(511)\n                    end\n                end,\n            },\n\n            ['Zabahf'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 3) then\n                        return quest:progressEvent(512)\n                    end\n                end,\n            },\n\n            ['Ekhu_Pesshyadha'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 4) then\n                        return quest:progressEvent(513)\n                    end\n                end,\n            },\n\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 5) then\n                        return quest:progressEvent(514)\n                    end\n                end,\n            },\n\n            ['Balakaf'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 6) then\n                        return quest:progressEvent(515)\n                    end\n                end,\n            },\n\n            ['Matifa'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 7) then\n                        return quest:progressEvent(516)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [510] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 1)\n                end,\n\n                [511] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 2)\n                end,\n\n                [512] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 3)\n                end,\n\n                [513] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 4)\n                end,\n\n                [514] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 5)\n                end,\n\n                [515] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 6)\n                end,\n\n                [516] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 7)\n                end,\n\n                [517] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BOWL_OF_SUTLAC) then\n                        quest:setVar(player, 'Prog', 0)\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n\n                [573] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
